// Endpoints, certificates and the trust a connection keeps (spec 038, research R9).
//
// The platform's certificate for a connection is generated by Laravel and written into
// a PKI folder of its own; the server's certificate is trusted only when its SHA-256
// fingerprint is the one a person accepted. node-opcua's automatic trust stays off.
const crypto = require("node:crypto");
const fs = require("node:fs");
const path = require("node:path");
const { OPCUACertificateManager } = require("node-opcua-certificate-manager");
const { convertPEMtoDER, exploreCertificate, toPem } = require("node-opcua-crypto");

// Accepted policies, strongest first. None is allowed behind a warning.
const STRENGTH = {
  Aes256_Sha256_RsaPss: 40,
  Basic256Sha256: 30,
  Aes128_Sha256_RsaOaep: 20,
  None: 0,
};
const REFUSED = { Basic128Rsa15: "unsafe", Basic256: "unsafe", Basic128: "unsafe" };
const MODES = { 1: "None", 2: "Sign", 3: "SignAndEncrypt" };
const TOKENS = { 0: "anonymous", 1: "username", 2: "certificate", 3: "issued" };

function policyName(uri) {
  return String(uri || "").split("#").pop() || "None";
}

function fingerprint(certificate) {
  return crypto.createHash("sha256").update(der(certificate)).digest("hex");
}

function der(certificate) {
  if (Buffer.isBuffer(certificate)) return certificate;
  if (typeof certificate === "string" && certificate.includes("BEGIN CERTIFICATE"))
    return convertPEMtoDER(certificate);
  return Buffer.from(certificate);
}

function label(policy, mode) {
  if (policy === "None") return "Not encrypted";
  return `${mode === "SignAndEncrypt" ? "Encrypted" : "Signed"} (${policy})`;
}

// What a server offers, ranked strongest first; refused choices last, with why.
function rankEndpoints(endpoints) {
  const choices = endpoints.map((endpoint) => {
    const policy = policyName(endpoint.securityPolicyUri);
    const mode = MODES[endpoint.securityMode] || String(endpoint.securityMode);
    const known = policy in STRENGTH;
    const refused = REFUSED[policy] || (known ? null : "unsupported");
    const server = endpoint.serverCertificate?.length ? Buffer.from(endpoint.serverCertificate) : null;
    return {
      policy,
      mode,
      label: label(policy, mode),
      strength: refused ? -1 : STRENGTH[policy] + (mode === "SignAndEncrypt" ? 2 : mode === "Sign" ? 1 : 0),
      refused,
      warning: policy === "None" && !refused ? "Values and sign-in travel unencrypted" : null,
      endpoint_url: endpoint.endpointUrl,
      sign_in: [...new Set((endpoint.userIdentityTokens || []).map((t) => TOKENS[t.tokenType]).filter(Boolean))],
      server_certificate: server,
      server_fingerprint: server ? fingerprint(server) : null,
    };
  });
  return choices.sort((a, b) => b.strength - a.strength);
}

// The application URI carried in a certificate, which a client must present as its own.
function applicationUri(certificate) {
  const info = exploreCertificate(der(certificate));
  return info.tbsCertificate.extensions?.subjectAltName?.uniformResourceIdentifier?.[0] || null;
}

// A connection's own PKI folder: its certificate and key, and a store that trusts
// nothing until told.
async function pkiFolder(root, connection, { certificate, privateKey }) {
  const folder = path.join(root, String(connection).replace(/[^A-Za-z0-9_-]/g, "_"));
  fs.mkdirSync(folder, { recursive: true, mode: 0o700 });
  const certificateFile = path.join(folder, "certificate.pem");
  const privateKeyFile = path.join(folder, "private-key.pem");
  fs.writeFileSync(certificateFile, toPem(der(certificate), "CERTIFICATE"), { mode: 0o600 });
  fs.writeFileSync(privateKeyFile, privateKey, { mode: 0o600 });
  const manager = new OPCUACertificateManager({
    rootFolder: path.join(folder, "pki"),
    automaticallyAcceptUnknownCertificate: false,
  });
  await manager.initialize();
  return { folder, manager, certificateFile, privateKeyFile, applicationUri: applicationUri(certificate) };
}

class CertificateChanged extends Error {
  constructor(seen) {
    super("The server presented a different certificate from the one accepted");
    this.reason = "server_certificate_changed";
    this.fingerprint = seen;
  }
}

// Trust the server's certificate only when it is the accepted one.
async function trustPinned(manager, certificate, pinned) {
  const seen = fingerprint(certificate);
  if (!pinned || seen !== String(pinned).toLowerCase().replace(/:/g, "")) throw new CertificateChanged(seen);
  await manager.trustCertificate(der(certificate));
  return seen;
}

module.exports = {
  CertificateChanged,
  REFUSED,
  STRENGTH,
  applicationUri,
  der,
  fingerprint,
  pkiFolder,
  policyName,
  rankEndpoints,
  trustPinned,
};
